import{_ as t,o as a,c as i,a8 as s}from"./chunks/framework.DpsX1MbM.js";const g=JSON.parse('{"title":"Draft export","description":"","frontmatter":{},"headers":[],"relativePath":"draft_export.md","filePath":"draft_export.md","lastUpdated":1795486067000}'),n={name:"draft_export.md"};function r(o,e,d,c,p,l){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="draft-export" tabindex="-1">Draft export <a class="header-anchor" href="#draft-export" aria-label="Permalink to &quot;Draft export&quot;">​</a></h1><p>Canonical training checkpoints include <code>config.json</code> beside training state. Its <code>specforge_artifact</code> field records format metadata outside the draft structure. Export reads that configuration; no training YAML is needed.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CHECKPOINT_PATH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODEL</span></span></code></pre></div><p><code>--export-mode standalone</code> is the default for every architecture, including MTP, DFlash and DSpark. It publishes a canonical draft directory. Native merge-back is an explicit public export mode and does not require a serving engine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CHECKPOINT_PATH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TARGET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MERGED_TARGET</span></span></code></pre></div><p>Native export selects an adapter by target model type and draft architecture. A missing adapter is an error; it never falls back to standalone. Registering an adapter does not change standalone exports. Dense Qwen3.5 MTP is the current built-in adapter; other combinations can register their own implementation. <code>--copy-target</code> is native-only. Native artifacts retain the target&#39;s configuration format, with <code>specforge_artifact: {format: native, version: 1}</code>; reload the canonical draft checkpoint to continue draft training.</p><p>Native export requires explicit target computation fields and checks them against the draft without changing the target configuration. Missing or conflicting fields are rejected; target RoPE parameters never inherit draft defaults. It rewrites shards containing old <code>mtp.*</code> tensors and links unaffected shards. <code>--copy-target</code> copies unaffected shards for a self-contained directory. Embedding/head copies are written under native names; The target is not modified.</p><p><code>--converter sglang</code> converts a standalone draft into a serving format. Native export already writes the target format, so explicit native mode takes no <code>--converter</code>. Serving compatibility is separate from these publication modes.</p><p>HF export writes canonical configuration, exact owned tensors, and model code for <code>AutoModel.from_pretrained(MODEL, trust_remote_code=True)</code>. SpecForge need not be installed. Use <code>specforge.loading.load_draft(MODEL, target=TARGET)</code> inside SpecForge. Target-bound token tables are omitted; callers must bind real target weights before running the HF model. They are never randomly initialized. SGLang cannot serve this directory; it needs a separate serving export. Model class names such as <code>DFlashDraftModel</code> may be shared by both implementations; their configuration formats and weight layouts still differ. The canonical format is identified by <code>model_type: specforge_draft</code> and its schema, not by the class name alone. <code>auto_map</code> selects the bundled implementation for Transformers. HF code bundling currently supports in-tree SpecForge architectures only; external architectures and ambiguous flattened module names are rejected before publication. Bundled code may import only torch, transformers and the standard library, so loading by Hub repo id needs nothing else; optional packages such as flash-attn are imported inside <code>try</code>, only when their backend is selected.</p><p>Export accepts canonical checkpoints containing <code>config.json</code>. Convert a historical checkpoint first with <code>scripts/convert_legacy_checkpoint.py</code> (<a href="/SpecForge/draft_training.html#checkpoint-and-configuration-boundary">usage</a>); export itself has no <code>--draft-config</code>. Token metadata (<code>bos_token_id</code>, <code>eos_token_id</code>, <code>pad_token_id</code>) is preserved. Use <code>--converter sglang</code> for serving conversion and <code>--target-model</code> for target metadata or native merge-back.</p><p>Export does not replace vocabulary mappings or accept arbitrary weight renames. Restore those explicitly before exporting. Missing, unexpected or misshaped weights fail before publication, and so does serving state that was never initialized (a reduced vocabulary without its mapping, an uninitialized DSpine transfer space). A nonempty output directory is rejected.</p><p>Both <code>save_draft(model, ...)</code> and canonical HF export use <code>write_artifact</code> for sharding, metadata and atomic directory publication. Model saving performs its wrapper/materialization checks first; export validates its checkpoint weight plan first. Training optimizer/RNG state remains owned by the training checkpoint manager.</p><h2 id="sglang" tabindex="-1">SGLang <a class="header-anchor" href="#sglang" aria-label="Permalink to &quot;SGLang&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --converter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sglang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CHECKPOINT_PATH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SERVING</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Explicit native export is independent of SGLang.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --export-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --checkpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CHECKPOINT_PATH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TARGET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MERGED_TARGET</span></span></code></pre></div><p>Native merge-back requires explicit <code>--export-mode native</code>. The SGLang converter only writes standalone serving artifacts. The old merge CLI has been removed.</p><p>The converter targets SGLang commit <code>c19e9c7d19a873498c4fee1d789596c1a2b6e6f0</code>, also pinned in CI. Each artifact records that revision and the converter version in <code>config.json</code>&#39;s <code>specforge_artifact</code> field. Conversion needs neither SGLang nor a GPU. Load/re-export/continued training use the canonical checkpoint; public draft loading rejects a serving artifact.</p><table tabindex="0"><thead><tr><th>Architecture</th><th>Serving format / restriction</th></tr></thead><tbody><tr><td>DFlash</td><td><code>DFlashDraftModel</code>; both token tables bound to the target</td></tr><tr><td>DFlash2</td><td><code>DFlash2DraftModel</code>, including convolution and selector</td></tr><tr><td>Domino</td><td><code>DFlashDraftModel</code> with explicit Domino projector settings</td></tr><tr><td>DSpark</td><td><code>DSparkDraftModel</code>; Markov head required; confidence head optional in static mode</td></tr><tr><td>EAGLE3</td><td><code>LlamaForCausalLMEagle3</code>; embedding bound, draft head owned</td></tr><tr><td>MTP</td><td>No standalone SGLang converter; use explicit native export for dense Qwen3.5 merge-back</td></tr><tr><td>DSpine, DMTP, P-EAGLE</td><td>Rejected: this pinned SGLang has no matching serving implementation</td></tr></tbody></table><p>Supported DFlash-family layers use uniform dense SiLU MLPs, standard residuals, GQA/MHA or MLA, and explicit supported RoPE settings. Layer-specific values are accepted only where SGLang can express them. Mixed causality is supported only for causal sliding layers with bidirectional full layers; <code>is_causal: null</code> selects that SGLang rule. Different head geometry across layers and window=1 are rejected. Noncausal sliding windows must cover at least one model block. The pinned converter rejects muP targets for DFlash2/Domino and offset RMSNorm for DSpark because their serving paths do not implement those computations. Unsupported component kinds and binding sets also fail. The pinned DSpark implementation chooses confidence-head use through its ragged-verification runtime mode; <code>cap-accept</code> exercises that head. Drafts without a confidence head require <code>SGLANG_RAGGED_VERIFY_MODE=static</code>. EAGLE3 supports multi-axis RoPE for VL targets; native MTP uses equal text positions on all axes.</p><p>Compared with historical exports, configuration fields such as causality, heads, rotary settings and block quantities are now written explicitly. Canonical module prefixes are removed for serving, vocabulary readiness is validated rather than serialized, and Domino uses SGLang&#39;s registered DFlash architecture name. These are format changes; tensors are not cast or transformed.</p><p>The pinned compatibility gate constructs real SGLang models and loads converted weights, records top-level and nested configuration reads for non-native models, and compares FP32 reference outputs. It checks that exported weights reach serving loaders, uses production recipe fields as an independent baseline, and covers MLA context projection, scaled/multi-axis RoPE and the DSpark stacked context-KV writer. It uses a dense attention oracle in place of paged KV-cache attention, so it is not an end-to-end serving/performance test. Separate tests cover native physical shard replacement and exact weight recovery, unsupported structures, and rejection of canonical HF configurations by SGLang&#39;s native constructor and generic Transformers compatibility gate. Run the gate with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPECFORGE_SGLANG_EXPORT_TESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TORCHDYNAMO_DISABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests.test_checkpoint.test_sglang_export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tests.test_checkpoint.test_sglang_compatibility</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h2 id="adding-family-adapters" tabindex="-1">Adding family adapters <a class="header-anchor" href="#adding-family-adapters" aria-label="Permalink to &quot;Adding family adapters&quot;">​</a></h2><p>Keep family-specific code in <code>specforge/checkpoint/formats/native/models/</code> or <code>specforge/checkpoint/formats/sglang/models/</code>. Add an explicit import in that package&#39;s <code>__init__.py</code> so registration runs when the package loads.</p><p>Native adapters call <code>register_native_target(model_type, architecture, ...)</code> and provide validation and export callbacks. They can reuse <code>native/writer.py</code> for weight checks and publication without changing the public exporter. Standalone serving converters use <code>register_converter(architecture)</code>; shared algorithm conversions remain in <code>sglang/converters.py</code>.</p><p>The SGLang Qwen3.5 module is a compatibility helper for the historical native command and parity tests, not a standalone MTP converter. Do not register it under <code>MTPDraftModel</code>: that would incorrectly select Qwen3.5 for every target. Native registration never selects an export mode or adds standalone engine support.</p>`,25)])])}const k=t(n,[["render",r]]);export{g as __pageData,k as default};
